-- Orrery engine: static file, installed as ~/.config/caelestia/orrery/engine.lua.
-- All user choices live in settings.lua, generated by the Orrery app.
local cfg = require("orrery.settings")
local M = { last = {} }

local function unbind(key) pcall(hl.unbind, key) end
local function rebind(key, action)
    if type(key) ~= "string" or not key:match("%S") then return end
    unbind(key)
    hl.bind(key, action)
end

-- Keyboard -------------------------------------------------------------------
if cfg.keyboard then
    hl.config({ input = {
        kb_layout          = cfg.keyboard.layout,
        kb_variant         = cfg.keyboard.variant,
        numlock_by_default = cfg.keyboard.numlock,
        repeat_rate        = cfg.keyboard.repeat_rate,
        repeat_delay       = cfg.keyboard.repeat_delay,
    } })
    if cfg.keyboard.switch_key then
        rebind(cfg.keyboard.switch_key, hl.dsp.exec_cmd("hyprctl switchxkblayout all next"))
    end
end

-- Default apps: rebind Caelestia's own shortcuts to the chosen commands ----------
local ok_vars, vars = pcall(require, "variables")
for var, command in pairs(cfg.apps or {}) do
    local keys = ok_vars and vars[var]
    if type(keys) == "string" then keys = { keys } end
    for _, key in ipairs(keys or {}) do
        rebind(key, hl.dsp.exec_cmd(command))
    end
end

-- Areas ----------------------------------------------------------------------
local areas = cfg.areas or {}
if #areas == 0 then return M end

hl.curve("orreryStandard", { type = "bezier", points = { { 0.2, 0 }, { 0, 1 } } })
hl.curve("orreryDecel", { type = "bezier", points = { { 0.05, 0.7 }, { 0.1, 1 } } })

local function animate(leaf, speed, bezier, style)
    if style == "none" then
        hl.animation({ leaf = leaf, enabled = false, speed = 1, bezier = bezier })
    else
        hl.animation({ leaf = leaf, enabled = true, speed = speed, bezier = bezier, style = style })
    end
end

local OPEN = { vertical = "slidefadevert 15%", horizontal = "slidefade 15%", fade = "fade", none = "none" }

local function open_animation(area)
    local style = OPEN[area.open_animation] or OPEN.vertical
    animate("specialWorkspaceIn", area.open_speed, "orreryDecel", style)
    animate("specialWorkspaceOut", area.open_speed, "orreryDecel", style)
end

local generation = 0
local function switch_animation(area, dir)
    local kind, style = area.switch_animation, nil
    if kind == "horizontal" then style = "slide " .. dir
    elseif kind == "vertical" then style = "slide " .. (dir == "right" and "bottom" or "top")
    else style = kind end
    -- Hyprland inverts the direction when leaving, so both use the same name
    animate("specialWorkspaceIn", area.switch_speed, "orreryStandard", style)
    animate("specialWorkspaceOut", area.switch_speed, "orreryStandard", style)
    generation = generation + 1
    local mine = generation
    hl.timer(function()
        if mine == generation then open_animation(area) end
    end, { timeout = math.floor(area.switch_speed * 100) + 100, type = "oneshot" })
end

local function windows_in(space)
    local found = {}
    for _, win in ipairs(hl.get_windows() or {}) do
        if win.mapped and win.workspace and win.workspace.name == space then found[#found + 1] = win end
    end
    return found
end

-- Area and space currently on screen
local function current()
    local special = hl.get_active_special_workspace()
    if not special then return end
    for _, area in ipairs(areas) do
        for i, space in ipairs(area.spaces) do
            if special.name == space.name then return area, i end
        end
    end
end

local function contains(area, name)
    for _, space in ipairs(area.spaces) do
        if space.name == name then return true end
    end
    return false
end

local function show(area, index)
    M.last[area.id] = index
    hl.dispatch(hl.dsp.focus({ workspace = area.spaces[index].name }))
end

-- Next space in the given direction. With need_windows, empty spaces are skipped.
local function neighbour_space(area, index, dir, need_windows)
    local step, n = dir == "right" and 1 or -1, #area.spaces
    for k = 1, n - 1 do
        local i = index + step * k
        if area.wrap then i = (i - 1) % n + 1 end
        if i < 1 or i > n then return end
        if not need_windows or #windows_in(area.spaces[i].name) > 0 then return i end
    end
end

local function has_neighbour(space, win, dir)
    for _, w in ipairs(windows_in(space)) do
        if w.address ~= win.address and not w.floating then
            local overlaps = w.at.y < win.at.y + win.size.y and win.at.y < w.at.y + w.size.y
            if overlaps and ((dir == "left" and w.at.x < win.at.x) or (dir == "right" and w.at.x > win.at.x)) then
                return true
            end
        end
    end
    return false
end

-- A window can carry the class or the desktop id of its app, in any case, depending on the toolkit
local function is_app(app, class)
    for _, c in ipairs(app.classes or { app.class }) do
        if c:lower() == (class or ""):lower() then return true end
    end
    return false
end

local function active_in(space)
    local win = hl.get_active_window()
    if win and win.workspace and win.workspace.name == space then return win end
end

function M.toggle(id)
    local area
    for _, a in ipairs(areas) do if a.id == id then area = a end end
    if not area then return end

    generation = generation + 1
    open_animation(area)

    local shown, index = current()
    if shown == area then
        M.last[area.id] = index
        hl.dispatch(hl.dsp.workspace.toggle_special((area.spaces[index].name:gsub("^special:", ""))))
        return
    end

    local running = {}
    for _, win in ipairs(hl.get_windows() or {}) do
        running[win.class] = true
        if area.bring_back then
            for _, space in ipairs(area.spaces) do
                for _, app in ipairs(space.apps) do
                    if is_app(app, win.class) and not (win.workspace and contains(area, win.workspace.name)) then
                        hl.dispatch(hl.dsp.window.move({ window = win, workspace = space.name, follow = false }))
                    end
                end
            end
        end
    end
    for _, space in ipairs(area.spaces) do
        for _, app in ipairs(space.apps) do
            local open = false
            for class in pairs(running) do open = open or is_app(app, class) end
            -- Starting an app that is already open would bring its window, and its workspace, to the front
            if app.autostart and app.command ~= "" and not open then
                hl.dispatch(hl.dsp.exec_cmd(app.command, { workspace = space.name .. " silent" }))
            end
        end
    end

    local target = M.last[area.id] or 1
    if not area.spaces[target] then target = 1 end
    if #windows_in(area.spaces[target].name) == 0 then
        for i, space in ipairs(area.spaces) do
            if #windows_in(space.name) > 0 then target = i break end
        end
    end
    show(area, target)
end

function M.focus(dir)
    local area, index = current()
    if not area or not area.arrows then
        hl.dispatch(hl.dsp.focus({ direction = dir }))
        return
    end
    local space = area.spaces[index].name
    local win = active_in(space)
    if win and has_neighbour(space, win, dir) then
        hl.dispatch(hl.dsp.focus({ direction = dir }))
        return
    end
    local i = neighbour_space(area, index, dir, true)
    if i then
        switch_animation(area, dir)
        show(area, i)
    end
end

function M.move(dir)
    local area, index = current()
    if not area or not area.arrows then
        hl.dispatch(hl.dsp.window.move({ direction = dir }))
        return
    end
    local space = area.spaces[index].name
    local win = active_in(space)
    if not win then return end
    if has_neighbour(space, win, dir) then
        hl.dispatch(hl.dsp.window.move({ direction = dir }))
        return
    end
    local i = neighbour_space(area, index, dir, false)
    if i then
        M.last[area.id] = i
        switch_animation(area, dir)
        hl.dispatch(hl.dsp.window.move({ workspace = area.spaces[i].name, follow = true }))
    end
end

local arrows = false
for _, area in ipairs(areas) do
    local id = area.id
    arrows = arrows or area.arrows
    rebind(area.key, function() M.toggle(id) end)
    for _, space in ipairs(area.spaces) do
        for _, app in ipairs(space.apps) do
            hl.window_rule({ match = { class = app.class_regex }, workspace = space.name .. " silent" })
        end
    end
end
if arrows then
    for _, dir in ipairs({ "left", "right" }) do
        rebind("SUPER + " .. dir, function() M.focus(dir) end)
        rebind("SUPER + SHIFT + " .. dir, function() M.move(dir) end)
    end
end

return M
